from threetears.evals import Eval

from board import display_c


def show(case):
    """The whole degree the board shows for the reading."""
    return {"shown_c": display_c(case["temp_f"])}


def within_half_degree(case, out):
    """The board is never more than half a degree from the logger's Celsius."""
    return abs(out["shown_c"] - case["temp_c"]) <= 0.5


board = Eval("data/dual_logged.jsonl", runner=show, grader=[within_half_degree], k=1)
